package com.bank.maint.service;

import java.util.logging.Logger;

// Finds the maximum non-adjacent benefit total (House Thief pattern).
public class MaintenancePlanService {
    private static final Logger log = Logger.getLogger(MaintenancePlanService.class.getName());

    public long maxBenefit(int[] values) {
        long incl = 0, excl = 0;                    // best including / excluding current
        for (int v : values) {
            long newIncl = excl + v;                // take current: add to excl of prev
            long newExcl = Math.max(incl, excl);    // skip current: best of prev two states
            incl = newIncl;
            excl = newExcl;
        }
        long result = Math.max(incl, excl);
        final long r = result;
        log.info(() -> "Maximum non-adjacent benefit = " + r);
        return result;
    }
}
