package com.bank.maint;

import com.bank.maint.service.MaintenancePlanService;
import java.util.logging.Logger;

public class MaintenancePlanApplication {
    private static final Logger log = Logger.getLogger(MaintenancePlanApplication.class.getName());

    public static void main(String[] args) {
        MaintenancePlanService service = new MaintenancePlanService();
        int[] values = {2, 7, 9, 3, 1};     // benefit per branch along the street
        long best = service.maxBenefit(values);
        log.info("Maximum maintenance benefit (no adjacent): " + best);
    }
}
